import { BotSDK } from '../sdk/index';
import { readFileSync, writeFileSync } from 'fs';
import { join } from 'path';

const env = JSON.parse(readFileSync(join(__dirname, '..', 'Bravo', 'bot.env'), 'utf8'));
const sdk = new BotSDK({ botUsername: env.BOT_USERNAME, password: env.PASSWORD, server: env.SERVER });
const CHAT = join(__dirname, '..', '_team', 'notes.md');

function log(msg: string) {
  const line = `[${new Date().toISOString()}] ${msg}`;
  console.log(line);
  writeFileSync(CHAT, readFileSync(CHAT, 'utf8') + line + '\n', { flag: 'a' });
}

function getEnemyPlayers() {
  const state = sdk.getState();
  if (!state) return [];
  return state.nearbyNpcs.filter(n => /rat|imp|zombie|monk|ghast|mage|dragon|demon|bandit|ogre|troll|spider|skeleton|bear|wolf|bat|vampire|hound|creature|animal/i.test(n.name) && n.level && n.level > 0 && !(n.name as string).toLowerCase().includes('giant rat') === false);
}

async function killEnemy(npc: any) {
  if (npc.distance > 5) {
    const r = await sdk.walkTo(npc.x, npc.z, 2);
    if (!r.success) return false;
  }
  const opt = npc.optionsWithIndex.find(o => /attack/i.test(o.text));
  if (!opt) return false;
  await sdk.sendInteractNpc(npc.index, opt.opIndex);
  await sdk.waitForCondition(s => {
    const p = s.player;
    return !p || p.isDead || p.combat.inCombat && p.combat.targetIndex === npc.index || s.combatEvents.some(e => e.type === 'damage_dealt' && e.targetIndex === npc.index);
  }, 8000);
  return true;
}

log('Starting kill loop. Bravo level 3.');
const seen = new Set<string>();
while (true) {
  const state = sdk.getState();
  const pc = state?.player;
  if (!pc) { log('No player state'); continue; }
  for (const npc of state.nearbyNpcs) {
    const name = npc.name as string;
    if (/rat/i.test(name) === false && /monster|imp|zombie|ghast|mage|dragon|demon|bandit|ogre|troll|spider|skeleton|demon/i.test(name) === false) continue;
    if (seen.has(name)) continue;
    const kt = await killEnemy(npc);
    if (kt) {
      log(`Killed ${name} (${npc.level})`);
      seen.add(name);
      break;
    }
  }
  if (pc.isDead) { log('Dead - respawn'); await sdk.waitForCondition(s => s.player && s.player.lifeId !== pc.lifeId, 5000); }
  await sdk.waitForTicks(2);
}
EOF
